   356→                let start = P::CellsPerExtBlob::USIZE.saturating_mul(i);
   357→                let end = P::CellsPerExtBlob::USIZE.saturating_add(start);
   358→                ContiguousVector::try_from_iter(cell_proofs[start..end].iter().copied())
   359→                    .map(|proofs| (cells, proofs))
   360→                    .map_err(Into::into)
   361→            })
